public class Main {
    // البحث الثنائي: يقسم المصفوفة إلى نصفين في كل خطوة
    public static int binarySearch(int[] arr, int target) {
        int left = 0, right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2; // تجنب تجاوز الحد الأقصى
            if (arr[mid] == target) {
                return mid;
            } else if (arr[mid] < target) {
                left = mid + 1; // ابحث في النصف الأيمن
            } else {
                right = mid - 1; // ابحث في النصف الأيسر
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] sorted = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        int target = 23;
        int index = binarySearch(sorted, target);
        System.out.println("Index of " + target + ": " + index);

        target = 10;
        index = binarySearch(sorted, target);
        System.out.println("Index of " + target + ": " + index);
    }
}

public class Main {
    public static void main(String[] args) {
        int[] arr = {1, 3, 5, 7, 9, 11};
        int target = 7;
        int low = 0, high = arr.length - 1;
        int result = -1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (arr[mid] == target) {
                result = mid;
                break;
            } else if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        System.out.println("Index of " + target + ": " + result);
    }
}

public class Main {
    static class Node {
        int key;
        Node left, right;
        Node(int k) { key = k; }
    }

    static Node insert(Node root, int key) {
        if (root == null) return new Node(key);
        if (key < root.key) {
            root.left = insert(root.left, key); // إدراج في اليسار
        } else if (key > root.key) {
            root.right = insert(root.right, key); // إدراج في اليمين
        }
        return root;
    }

    static void inorder(Node root) {
        if (root == null) return;
        inorder(root.left);
        System.out.print(root.key + " ");
        inorder(root.right);
    }

    public static void main(String[] args) {
        Node root = null;
        int[] values = {50, 30, 70, 20, 40, 60, 80};
        for (int v : values) {
            root = insert(root, v);
        }
        inorder(root);
        System.out.println();
    }
}

