class BST {
    int val;
    BST left, right;
    BST(int v) { val = v; left = right = null; }

    static boolean search(BST node, int key) {
        if (node == null) return false;
        if (node.val == key) return true;
        return key < node.val ? search(node.left, key) : search(node.right, key);
    }
}

