public class Main {
    // حساب فيبوناتشي باستخدام مصفوفة لحفظ النتائج السابقة
    public static long fibonacci(int n) {
        if (n <= 1) return n;
        long[] dp = new long[n + 1];
        dp[0] = 0;
        dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
    }

    public static void main(String[] args) {
        int n = 50;
        System.out.println("Fibonacci(" + n + ") = " + fibonacci(n));
    }
}

