        int num = 84;
        System.out.print("Prime factors of " + num + ": ");
        // نبدأ بأصغر عامل أولي وهو 2
        for (int factor = 2; factor * factor <= num; factor++) {
            while (num % factor == 0) {
                System.out.print(factor + " ");
                num /= factor;
            }
        }
        // إذا بقي عدد أكبر من 1 فهو عامل أولي
        if (num > 1) System.out.print(num);
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 30;
        boolean[] isPrime = new boolean[n + 1];
        // نفترض أن جميع الأعداد أولية ثم نستبعد المضاعفات
        for (int i = 2; i <= n; i++) isPrime[i] = true;
        for (int p = 2; p * p <= n; p++) {
            if (isPrime[p]) {
                for (int multiple = p * p; multiple <= n; multiple += p) {
                    isPrime[multiple] = false;
                }
            }
        }
        System.out.print("Primes up to " + n + ": ");
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) System.out.print(i + " ");
        }
        System.out.println();
    }
}

