import java.util.*;

public class Main {
    public static void main(String[] args) {
        // رسومُ الاشتراك السنويّ لكلّ ناشر (وحداتٌ افتراضيّةٌ للتوضيح)
        Map<String, Integer> fee = new LinkedHashMap<>();
        fee.put("PubA", 100);
        fee.put("PubB", 80);
        fee.put("PubC", 60);
        fee.put("PubD", 40);
        Map<String, Integer> budget = new LinkedHashMap<>();
        budget.put("BigUni", 300);
        budget.put("MidUni", 150);
        budget.put("NewUni", 50);
        // قبل المكتبة: كلُّ جامعةٍ تشتري وحدها بقدر ميزانيّتها، فتتكرّر الاشتراكات وتتفاوت المصادر
        Map<String, Integer> copies = new TreeMap<>();
        int separate = 0;
        System.out.println("-- separate subscriptions --");
        for (String uni : budget.keySet()) {
            int left = budget.get(uni);
            List<String> owned = new ArrayList<>();
            for (String pub : fee.keySet()) {
                if (fee.get(pub) <= left) {
                    left -= fee.get(pub);
                    owned.add(pub);
                    copies.merge(pub, 1, Integer::sum);
                    separate += fee.get(pub);
                }
            }
            System.out.println(uni + " reads " + owned);
        }
        System.out.println("copies bought: " + copies + ", total cost = " + separate);
        // المكتبةُ المركزيّة: عقدٌ واحدٌ لكلّ ناشر، وتصل المصادرُ كلُّها إلى كلّ جامعة
        int central = 0;
        for (int f : fee.values()) central += f;
        System.out.println("-- central library --");
        System.out.println("every university reads " + fee.keySet() + ", total cost = " + central);
        System.out.println("saved = " + (separate - central));
    }
}

