public class Main {
    // كلُّ لقطةٍ تحفظ أبَها، فتتكوّن سلسلةٌ تعيد التاريخَ كلَّه
    static Map<String, String[]> commits = new LinkedHashMap<>(); // id -> {parent, message}
    static Map<String, String> branches = new TreeMap<>();        // الفرع -> آخرُ لقطة
    static int counter = 0;

    static void commit(String branch, String message) {
        String id = "c" + (++counter);
        String parent = branches.get(branch);
        commits.put(id, new String[] { parent, message });
        branches.put(branch, id); // الفرعُ مؤشّرٌ يتحرّك، واللقطةُ القديمةُ تبقى كما هي
        System.out.println(branch + " <- " + id + " (parent " + parent + ")");
    }

    static void printLog(String branch) {
        System.out.print(branch + ":");
        for (String id = branches.get(branch); id != null; id = commits.get(id)[0]) {
            System.out.print(" " + id + "(" + commits.get(id)[1] + ")");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        commit("main", "init");
        commit("main", "add login");
        branches.put("feature", branches.get("main")); // إنشاءُ فرعٍ = مؤشّرٌ جديدٌ إلى اللقطة نفسها
        commit("feature", "login form");
        commit("main", "fix typo");
        printLog("main");
        printLog("feature");
        System.out.println("commits stored = " + commits.size());
    }
}

public class Main {
    enum State { OPEN, APPROVED, MERGED }

    static class PullRequest {
        final String title;
        State state = State.OPEN;
        boolean checksPassed = false;

        PullRequest(String title) { this.title = title; }

        void review(boolean approve) {
            // الموافقةُ تنقل الطلبَ إلى APPROVED، أما التعليقُ السلبيّ فلا يغيّر الحالة هنا
            if (approve && state == State.OPEN) state = State.APPROVED;
            System.out.println("review approve=" + approve + " -> " + state);
        }

        void merge() {
            // حمايةُ الفرع: لا دمجَ قبل موافقةٍ ونجاحِ الفحوص معاً
            if (state != State.APPROVED || !checksPassed) {
                System.out.println("merge blocked: state=" + state + ", checks=" + checksPassed);
                return;
            }
            state = State.MERGED;
            System.out.println("merged: " + title + " -> " + state);
        }
    }

    public static void main(String[] args) {
        PullRequest pr = new PullRequest("Add login screen");
        pr.merge();
        pr.checksPassed = true; // نجحت فحوص CI
        pr.review(true);
        pr.merge();
        PullRequest pr2 = new PullRequest("Broken build");
        pr2.review(false);
        pr2.merge();
    }
}

public class Main {
    static final String[] OPINION_WORDS = {"best", "better", "favorite"};

    static String screen(String title, boolean hasCodeOrError) {
        for (String w : OPINION_WORDS) {
            // السؤالُ المبنيّ على الرأي لا جوابَ موضوعيَّ له، فيُغلق
            if (title.toLowerCase().contains(w)) return "closed (opinion-based)";
        }
        // سؤالٌ بلا كودٍ أو رسالةِ خطأٍ محدّدة واسعٌ لا يُحَلّ بجوابٍ واحد
        if (!hasCodeOrError) return "closed (too broad)";
        return "open";
    }

    public static void main(String[] args) {
        String[] titles = {
            "What is the best programming language?",
            "NullPointerException in onCreate after findViewById",
            "How do I build an app?",
            "Toast not showing after makeText"};
        boolean[] hasCode = {false, true, false, true};
        int open = 0;
        for (int i = 0; i < titles.length; i++) {
            String verdict = screen(titles[i], hasCode[i]);
            if (verdict.equals("open")) open++;
            System.out.println("Q" + (i + 1) + " " + verdict + ": " + titles[i]);
        }
        // السمعةُ تكافئ الإجابةَ الدقيقة: +10 لكلّ تصويتٍ مؤيّد و+15 عند القبول
        int reputation = 1;
        for (String event : new String[] {"upvote", "upvote", "accepted"}) {
            reputation += event.equals("accepted") ? 15 : 10;
            System.out.println(event + " -> reputation " + reputation);
        }
        System.out.println("open questions = " + open);
    }
}

