public class Main {
    static final int COMPILE_COST = 5; // كلفةُ تحويل دالةٍ واحدة من Bytecode إلى لغة الآلة
    static final int NATIVE_CALL = 1;  // كلفةُ استدعاءٍ بعد التحويل

    public static void main(String[] args) {
        String[] methods = {"onCreate", "draw", "save"};
        int[] callsPerLaunch = {1, 40, 3};
        int totalCalls = 0;
        for (int c : callsPerLaunch) totalCalls += c;
        // ART يحوّل الدوالَّ كلَّها مرّةً واحدة وقتَ التثبيت، قبل أن ينتظر المستخدم
        int installCost = 0;
        for (String m : methods) {
            installCost += COMPILE_COST;
            System.out.println("install: " + m + " -> machine code");
        }
        System.out.println("install cost = " + installCost + " (paid once, before the first launch)");
        int artTotal = 0, dalvikTotal = 0;
        for (int launch = 1; launch <= 3; launch++) {
            int art = totalCalls * NATIVE_CALL;
            // Dalvik يترجم أثناء التشغيل، فيدفع المستخدمُ كلفةَ الترجمة في كلّ فتحٍ للتطبيق
            int dalvik = methods.length * COMPILE_COST + totalCalls * NATIVE_CALL;
            artTotal += art;
            dalvikTotal += dalvik;
            System.out.println("launch " + launch + ": ART runtime=" + art + ", Dalvik runtime=" + dalvik);
        }
        System.out.println("total while user waits: ART=" + artTotal + ", Dalvik=" + dalvikTotal);
    }
}

public class Main {
    // المشغِّلُ يكتبه مصنّعُ الجهاز فوق نواة لينكس؛ وكلُّ مصنّعٍ يقرأ العتادَ بصيغةٍ مختلفة
    interface GpsDriver {
        double[] read();
    }

    static class VendorXDriver implements GpsDriver {
        public double[] read() {
            String raw = "$GPGGA,24.7136N,46.6753E";
            System.out.println("  driver X raw: " + raw);
            String[] p = raw.split(",");
            return new double[] {Double.parseDouble(p[1].replace("N", "")),
                Double.parseDouble(p[2].replace("E", ""))};
        }
    }

    static class VendorYDriver implements GpsDriver {
        public double[] read() {
            String raw = "LAT=24.7136;LON=46.6753";
            System.out.println("  driver Y raw: " + raw);
            String[] p = raw.split(";");
            return new double[] {Double.parseDouble(p[0].substring(4)),
                Double.parseDouble(p[1].substring(4))};
        }
    }

    // واجهةُ Android API وسيطٌ: تنقل الطلبَ إلى المشغِّل وتعيد للتطبيق صيغةً واحدة
    static class LocationManager {
        final GpsDriver driver;
        LocationManager(GpsDriver driver) { this.driver = driver; }
        double[] getLastLocation() {
            System.out.println("  framework: forwarding request to the Linux driver");
            return driver.read();
        }
    }

    // كودُ التطبيق واحدٌ لا يتغيّر مهما اختلف الجهاز
    static void appCode(LocationManager lm) {
        double[] loc = lm.getLastLocation();
        System.out.println("  app got lat=" + loc[0] + " lon=" + loc[1]);
    }

    public static void main(String[] args) {
        System.out.println("device with chip X:");
        appCode(new LocationManager(new VendorXDriver()));
        System.out.println("device with chip Y:");
        appCode(new LocationManager(new VendorYDriver()));
    }
}

