public class Main {
    public static void main(String[] args) throws Exception {
        // ملفُّ الواجهة نصُّ XML: كلُّ عنصرٍ يحمل معرّفاً يربطه كودُ جافا به
        String layout = "<LinearLayout>"
            + "<TextView id=\"title\" text=\"Welcome\"/>"
            + "<EditText id=\"username\" hint=\"Name\"/>"
            + "<Button id=\"login\" text=\"Login\"/>"
            + "</LinearLayout>";
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder()
                .parse(new InputSource(new StringReader(layout)));
