        Map<String, Element> views = new LinkedHashMap<>();
        NodeList children = doc.getDocumentElement().getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node n = children.item(i);
            if (n instanceof Element) {
                Element el = (Element) n;
                views.put(el.getAttribute("id"), el);
            }
        }
        System.out.println("views: " + views.keySet());
        Element button = views.get("login");
        System.out.println(button.getTagName() + " text=\"" + button.getAttribute("text") + "\"");
    }
}

