public class Main {
    // مستوياتُ السجلّ مرتّبة: V < D < I < W < E، والمرشّحُ يُخفي ما هو أدنى منه
    static final Map<String, Integer> LEVEL = Map.of("V", 1, "D", 2, "I", 3, "W", 4, "E", 5);
    static int minLevel = 3; // في الإنتاج نُخفي الرسائلَ التفصيليّة
    static int created = 0, shown = 0;

    static void log(String level, String tag, String msg) {
        if (LEVEL.get(level) < minLevel) return; // الرسالةُ أدنى من المرشّح فلا تُطبع
        System.out.println(level + "/" + tag + ": " + msg);
    }

    static class Toast {
        final String msg;
        final boolean longDuration;
        private Toast(String msg, boolean longDuration) {
            this.msg = msg;
            this.longDuration = longDuration;
            created++;
        }
        static Toast makeText(String msg, boolean longDuration) { return new Toast(msg, longDuration); }
        // makeText وحدها تبني الكائنَ فقط؛ الرسالةُ لا تظهر للمستخدم حتى يُستدعى show()
        void show() {
            shown++;
            System.out.println("TOAST(" + (longDuration ? "long" : "short") + "): " + msg);
        }
    }

    public static void main(String[] args) {
        System.out.println("min level = " + minLevel);
        log("D", "Login", "field count = 2");
        log("I", "Login", "user opened screen");
        log("E", "Login", "wrong password");
        Toast.makeText("Saved", false).show();
        Toast.makeText("Network is offline", true); // نُسي show()
        System.out.println("toasts created = " + created + ", shown = " + shown);
    }
}

