import java.util.*;

public class Main {
    // مستكشف المشروع يجمع الملفاتِ الفعليّةَ في أربع مجموعات
    static String group(String path) {
        if (path.endsWith("AndroidManifest.xml")) return "manifests";
        if (path.contains("/build/generated/")) return "java (generated)";
        if (path.contains("/src/main/java/")) return "java";
        return "res";
    }

    public static void main(String[] args) {
        String[] files = {
            "app/src/main/AndroidManifest.xml",
            "app/src/main/java/com/example/hello/MainActivity.java",
            "app/build/generated/com/example/hello/R.java",
            "app/src/main/res/layout/activity_main.xml",
            "app/src/main/res/values/strings.xml"};
        Map<String, List<String>> explorer = new LinkedHashMap<>();
        for (String g : new String[] {"manifests", "java", "java (generated)", "res"}) {
            explorer.put(g, new ArrayList<>());
        }
        for (String f : files) {
            String name = f.contains("/res/") ? f.substring(f.indexOf("/res/") + 5)
                                              : f.substring(f.lastIndexOf('/') + 1);
            explorer.get(group(f)).add(name);
        }
        for (Map.Entry<String, List<String>> e : explorer.entrySet()) {
            System.out.println(e.getKey() + ": " + e.getValue());
        }
        // الملفُّ المولَّد يُعاد توليدُه من الموارد عند كلّ بناء، فيضيع أيُّ تعديلٍ يدويٍّ فيه
