public class Main {
    static Map<String, Map<String, String>> graph = new LinkedHashMap<>(); // الجزء -> {الإجراء -> التالي}
    static Deque<String> backStack = new ArrayDeque<>();
    static String current;
    static int navigations = 0;

    static void navigate(String action) {
        String next = graph.get(current).get(action);
        backStack.push(current);
        navigations++;
        System.out.println(current + " --" + action + "--> " + next);
        current = next;
    }

    public static void main(String[] args) throws Exception {
        // ملفُّ nav_graph.xml يحدّد الجزءَ الأوّل ومساراتِ الانتقال بين الأجزاء
        String xml = "<navigation startDestination=\"FirstFragment\">"
            + "<fragment id=\"FirstFragment\"><action id=\"next\" to=\"SecondFragment\"/></fragment>"
            + "<fragment id=\"SecondFragment\"><action id=\"previous\" to=\"FirstFragment\"/></fragment>"
            + "</navigation>";
        Element root = DocumentBuilderFactory.newInstance().newDocumentBuilder()
            .parse(new InputSource(new StringReader(xml))).getDocumentElement();
        NodeList fragments = root.getElementsByTagName("fragment");
        for (int i = 0; i < fragments.getLength(); i++) {
            Element f = (Element) fragments.item(i);
            Element a = (Element) f.getElementsByTagName("action").item(0);
            graph.put(f.getAttribute("id"), Map.of(a.getAttribute("id"), a.getAttribute("to")));
        }
        // نشاطٌ واحد (MainActivity) تتبدّل فيه الأجزاءُ بدل نشاطٍ جديدٍ لكلّ شاشة
        current = root.getAttribute("startDestination");
        System.out.println("MainActivity hosts " + graph.keySet() + ", start = " + current);
        navigate("next");
        navigate("previous");
        navigate("next");
        System.out.println("now = " + current + ", back stack = " + backStack);
        System.out.println("Activities = 1; one-Activity-per-screen would have started " + navigations + " more");
    }
}

import java.util.*;

public class Main {
    interface GpsListener { void onLocation(double lat, double lon); }

    static class Emulator {
        final Map<String, Integer> installed = new TreeMap<>(); // التطبيق -> رقمُ البناء المثبّت
        int width = 1080, height = 1920;
        GpsListener gps;

        // Run في أندرويد ستوديو يبني APK ويثبّته فعلاً؛ وكلُّ تعديلٍ في الكود يحتاج تثبيتاً جديداً
        void run(String app) {
            installed.merge(app, 1, Integer::sum);
            System.out.println("Run: installed " + app + " build " + installed.get(app));
        }

        void launchFromDrawer(String app) {
            System.out.println(installed.containsKey(app)
                ? "drawer: launching " + app + " build " + installed.get(app)
                : "drawer: " + app + " is not installed");
        }

        void rotate() {
            int t = width;
            width = height;
            height = t;
            System.out.println("rotate: " + width + "x" + height);
        }

        // الحاسوبُ بلا مستشعر GPS، فترسل الإعداداتُ المتقدّمة موقعاً وهميّاً للتطبيق
        void mockLocation(double lat, double lon) {
            if (gps != null) gps.onLocation(lat, lon);
        }
    }

    public static void main(String[] args) {
        Emulator avd = new Emulator();
        avd.run("HelloApp");
        avd.run("HelloApp"); // بعد تعديل الكود: تثبيتٌ جديدٌ يستبدل القديم
        avd.launchFromDrawer("HelloApp"); // يعمل ولو أُغلق ستوديو
        avd.launchFromDrawer("OtherApp");
        avd.gps = (lat, lon) -> System.out.println("app received GPS " + lat + "," + lon);
        avd.mockLocation(24.7136, 46.6753);
        avd.rotate();
    }
}

