class Config {
    String device; int smallestWidthDp; boolean landscape;
    Config(String d, int sw, boolean l) { device = d; smallestWidthDp = sw; landscape = l; }
}

public class Main {
    static final String[] FOLDERS = {"layout", "layout-land", "layout-sw600dp", "layout-sw600dp-land"};
    static final int[] MIN_SW = {0, 0, 600, 600};
    static final boolean[] NEEDS_LAND = {false, true, false, true};

    static String resolve(Config c) {
        String best = null; int bestScore = -1;
        for (int i = 0; i < FOLDERS.length; i++) {
            boolean ok = c.smallestWidthDp >= MIN_SW[i] && (!NEEDS_LAND[i] || c.landscape);
            System.out.println("  " + FOLDERS[i] + (ok ? " matches" : " rejected"));
            // smallestWidth أعلى أسبقية من الاتجاه، لذا يُوزن أكثر
            int score = MIN_SW[i] * 10 + (NEEDS_LAND[i] ? 1 : 0);
            if (ok && score > bestScore) { bestScore = score; best = FOLDERS[i]; }
        }
        return best;
    }

    public static void main(String[] args) {
        Config[] devices = {
            new Config("phone-portrait", 360, false), new Config("phone-landscape", 360, true),
            new Config("tablet-portrait", 720, false), new Config("tablet-landscape", 720, true) };
        for (Config c : devices) {
            System.out.println(c.device + " (sw" + c.smallestWidthDp + "dp)");
            System.out.println("  -> " + resolve(c));
        }
    }
}

