class Box {
    String id; int w; int x;
    Box(String id, int w) { this.id = id; this.w = w; }
    int end() { return x + w; }
}

public class Main {
    public static void main(String[] args) {
        int parentW = 1080;
        Box a = new Box("A", 200), b = new Box("B", 300), c = new Box("C", 180);
        // A: القيد start بحافة الأب مع هامش 40
        a.x = 40;
        System.out.println("A start->parent.start +40  x=" + a.x + " end=" + a.end());
        // B: القيد start بنهاية A مع هامش 24، فيتحرك B إن تحرك A
        b.x = a.end() + 24;
        System.out.println("B start->A.end +24  x=" + b.x + " end=" + b.end());
        // C مقيَّد من الطرفين (B.end و parent.end): الانحياز يقسم المساحة الحرة
        int free = parentW - b.end() - c.w;
        for (float bias : new float[]{0f, 0.25f, 0.5f, 1f}) {
            c.x = b.end() + Math.round(free * bias);
            System.out.println("C bias=" + bias + " free=" + free + " x=" + c.x + " end=" + c.end());
        }
    }
}

import java.util.Arrays;

public class Main {
    static String pad(String s, int w) { return String.format("%-" + w + "s", s); }

    public static void main(String[] args) {
        String[][] rows = { {"Item", "Qty", "Price"}, {"Notebook", "12", "3.50"}, {"Calculator", "2", "18.00"} };
        int cols = 3, padding = 2, tableWidth = 30, stretchCol = 1;
        int[] width = new int[cols];
        // عرض العمود = أعرض خلية فيه، لأن TableLayout يوحّد الأعمدة بين كل الصفوف
        for (String[] r : rows)
            for (int c = 0; c < cols; c++) width[c] = Math.max(width[c], r[c].length() + padding);
        int used = 0;
        for (int w : width) used += w;
        System.out.println("natural widths=" + Arrays.toString(width) + " used=" + used);
        // stretchColumns: العمود المحدد وحده يأخذ المساحة الفائضة
        width[stretchCol] += tableWidth - used;
        System.out.println("stretched widths=" + Arrays.toString(width));
        for (String[] r : rows) {
            StringBuilder line = new StringBuilder("|");
            for (int c = 0; c < cols; c++) line.append(pad(" " + r[c], width[c])).append("|");
            System.out.println(line);
        }
    }
}

class View {
    String name, widthSpec; int fixedDp, contentDp, padding, margin;
    View(String n, String spec, int fixed, int content, int pad, int mar) {
        name = n; widthSpec = spec; fixedDp = fixed; contentDp = content; padding = pad; margin = mar;
    }
    int measureWidth(int available) {
        if (widthSpec.equals("match_parent")) return available - 2 * margin;
        if (widthSpec.equals("wrap_content")) return contentDp + 2 * padding;
        return fixedDp;
    }
}

public class Main {
    public static void main(String[] args) {
        int screen = 360, parentPadding = 8;
        int available = screen - 2 * parentPadding;
        System.out.println("available width=" + available + "dp");
        View[] views = {
            new View("title", "match_parent", 0, 120, 16, 8),
            new View("button", "wrap_content", 0, 90, 12, 8),
            new View("icon", "48dp", 48, 0, 0, 4) };
        for (View v : views) {
            int w = v.measureWidth(available);
            // الحشوة داخل حدود العنصر، أما الهامش فمساحة خارجه تفصله عن جاره
            System.out.println(v.name + ": " + v.widthSpec + " -> width=" + w + "dp, inner=" + (w - 2 * v.padding)
                + "dp, takes " + (w + 2 * v.margin) + "dp in the row");
        }
    }
}

public class Main {
    static void distribute(String label, int total, int[] natural, int[] weight) {
        int used = 0, sumWeight = 0;
        for (int i = 0; i < natural.length; i++) { used += natural[i]; sumWeight += weight[i]; }
        int extra = total - used;
        System.out.println(label + ": extra space=" + extra + " sumWeight=" + sumWeight);
        for (int i = 0; i < natural.length; i++) {
            // المساحة الفائضة فقط تُوزَّع بنسبة الوزن، فوق الحجم الطبيعي
            int w = natural[i] + (sumWeight == 0 ? 0 : extra * weight[i] / sumWeight);
            System.out.println("  child" + i + " natural=" + natural[i] + " weight=" + weight[i] + " -> " + w);
        }
    }

    public static void main(String[] args) {
        distribute("0dp + weights", 360, new int[]{0, 0, 0}, new int[]{1, 2, 1});
        distribute("wrap + weights", 360, new int[]{100, 60, 80}, new int[]{0, 1, 1});
        int slot = 90, view = 50;
        String[] gravity = {"start", "center", "end"};
        int[] offset = {0, (slot - view) / 2, slot - view};
        for (int i = 0; i < 3; i++) {
            System.out.println("gravity=" + gravity[i] + " x=" + offset[i] + ".." + (offset[i] + view)
                + " in slot of " + slot);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int cards = 10, cardH = 150, gap = 10, pad = 8, viewport = 600;
        int content = pad * 2 + cards * cardH + (cards - 1) * gap;
        int maxScroll = content - viewport;
        System.out.println("content=" + content + " viewport=" + viewport + " maxScroll=" + maxScroll);
        int scrollY = 0;
        int[] swipes = {400, 400, 400, -2000};
        for (int dy : swipes) {
            // ScrollView لا يتجاوز بداية المحتوى ولا نهايته مهما كانت الحركة
            scrollY = Math.max(0, Math.min(maxScroll, scrollY + dy));
            int first = -1, last = -1;
            for (int i = 0; i < cards; i++) {
                int top = pad + i * (cardH + gap);
                if (top + cardH > scrollY && top < scrollY + viewport) {
                    if (first < 0) first = i;
                    last = i;
                }
            }
            System.out.println("swipe " + dy + " -> scrollY=" + scrollY + " visible cards " + first + ".." + last);
        }
    }
}

public class Main {
    static boolean entire, visible, foreground;

    static void call(String cb) {
        // كل زوج من الدوال يفتح عمرًا ويغلقه: Create/Destroy ثم Start/Stop ثم Resume/Pause
        switch (cb) {
            case "onCreate": entire = true; break;
            case "onStart": visible = true; break;
            case "onResume": foreground = true; break;
            case "onPause": foreground = false; break;
            case "onStop": visible = false; break;
            case "onDestroy": entire = false; break;
            default: break;
        }
        System.out.printf("%-10s entire=%d visible=%d foreground=%d%n",
            cb, entire ? 1 : 0, visible ? 1 : 0, foreground ? 1 : 0);
    }

    public static void main(String[] args) {
        String[][] phases = {
            {"-- launch", "onCreate", "onStart", "onResume"},
            {"-- press Home", "onPause", "onStop"},
            {"-- reopen app", "onRestart", "onStart", "onResume"},
            {"-- press Back", "onPause", "onStop", "onDestroy"} };
        for (String[] p : phases) {
            System.out.println(p[0]);
            for (int i = 1; i < p.length; i++) call(p[i]);
        }
    }
}

