import java.util.*;

public class Main {
    enum State { CREATED, STARTED, RESUMED, PAUSED, STOPPED, DESTROYED }
    static final Map<State, List<State>> LEGAL = new EnumMap<>(State.class);
    static State current = State.CREATED;

    static void go(State next) {
        // لا يصل النظام إلى حالة إلا عبر الحالة المجاورة لها في الدورة
        boolean ok = LEGAL.get(current).contains(next);
        System.out.println(current + " -> " + next + (ok ? " ok" : " REJECTED"));
        if (ok) current = next;
    }

    public static void main(String[] args) {
        LEGAL.put(State.CREATED, List.of(State.STARTED, State.DESTROYED));
        LEGAL.put(State.STARTED, List.of(State.RESUMED, State.STOPPED));
        LEGAL.put(State.RESUMED, List.of(State.PAUSED));
        LEGAL.put(State.PAUSED, List.of(State.RESUMED, State.STOPPED));
        LEGAL.put(State.STOPPED, List.of(State.STARTED, State.DESTROYED));
        LEGAL.put(State.DESTROYED, List.of());
        String[] script = {"STARTED", "RESUMED", "DESTROYED", "PAUSED", "RESUMED", "PAUSED", "STOPPED",
            "STARTED", "RESUMED", "PAUSED", "STOPPED", "DESTROYED", "STARTED"};
        for (String s : script) go(State.valueOf(s));
    }
}

import java.util.*;
class Fragment {
    String name;
    Fragment(String n) { name = n; }
    void log(String ev) { System.out.println("  " + name + "." + ev); }
    void show() { log("onCreateView"); log("onStart"); log("onResume"); }
    void hide() { log("onPause"); log("onStop"); log("onDestroyView"); }
}
class FragmentManager {
    Deque<Fragment> backStack = new ArrayDeque<>();
    Fragment current;
    void replace(Fragment f, boolean addToBackStack) {
        System.out.println("replace(" + f.name + ", addToBackStack=" + addToBackStack + ")");
        if (current != null) {
            current.hide();
            // الجزء المحفوظ في المكدس تُدمَّر واجهته فقط، وغيره يُدمَّر كاملاً
            if (addToBackStack) backStack.push(current); else current.log("onDestroy");
        }
        current = f;
        f.show();
    }
    boolean popBackStack() {
        if (backStack.isEmpty()) return false;
        System.out.println("popBackStack()");
        current.hide();
        current.log("onDestroy");
        current = backStack.pop();
        current.show();
        return true;
    }
}
public class Main {
    public static void main(String[] args) {
        FragmentManager fm = new FragmentManager();
        fm.replace(new Fragment("List"), false);
        fm.replace(new Fragment("Detail"), true);
        fm.popBackStack();
        System.out.println("back again handled: " + fm.popBackStack());
    }
}

