class AlertBuilder {
    String title = "", message = "", positive = "OK";
    boolean cancelable = true;

    AlertBuilder setTitle(String t) { title = t; return log("setTitle"); }
    AlertBuilder setMessage(String m) { message = m; return log("setMessage"); }
    AlertBuilder setPositiveButton(String p) { positive = p; return log("setPositiveButton"); }
    AlertBuilder setCancelable(boolean c) { cancelable = c; return log("setCancelable"); }

    AlertBuilder log(String call) { System.out.println("  " + call + " -> " + this); return this; }
    public String toString() { return "[" + title + "|" + message + "|" + positive + "|cancel=" + cancelable + "]"; }
}

public class Main {
    public static void main(String[] args) {
        AlertBuilder b = new AlertBuilder();
