import java.util.*;

class Holder {
    int id;
    Holder(int id) { this.id = id; }
}

public class Main {
    static int created = 0, bound = 0;
    static Deque<Holder> pool = new ArrayDeque<>();
    static Map<Integer, Holder> onScreen = new TreeMap<>();

    static void scrollTo(int first, int visible) {
        // الصف الذي خرج من الشاشة يعود إلى المجمّع بدل أن يُتلف
        for (Iterator<Map.Entry<Integer, Holder>> it = onScreen.entrySet().iterator(); it.hasNext();) {
            Map.Entry<Integer, Holder> e = it.next();
            if (e.getKey() < first || e.getKey() >= first + visible) { pool.push(e.getValue()); it.remove(); }
        }
        int reused = 0, madeNew = 0;
        for (int pos = first; pos < first + visible; pos++) {
            if (onScreen.containsKey(pos)) continue;
            Holder h = pool.poll();
            if (h == null) { h = new Holder(++created); madeNew++; } else reused++;
            bound++;
            onScreen.put(pos, h);
        }
        StringBuilder rows = new StringBuilder();
        for (Map.Entry<Integer, Holder> e : onScreen.entrySet()) rows.append(" ").append(e.getKey()).append(":#").append(e.getValue().id);
        System.out.println("first=" + first + " reused=" + reused + " new=" + madeNew + " | created=" + created + " bound=" + bound);
        System.out.println("  rows" + rows);
    }

    public static void main(String[] args) {
        for (int first : new int[]{0, 3, 6, 50, 0}) scrollTo(first, 6);
        System.out.println("adapter has 1000 items but only " + created + " holders exist");
    }
}

import java.util.*;
class NotesAdapter {
    List<String> data = new ArrayList<>(List.of("Today", "Math notes", "Physics lab", "Yesterday"));
    List<String> attached = new ArrayList<>();
    int getItemViewType(int pos) { return data.get(pos).contains(" ") ? 1 : 0; }
    String onCreateViewHolder(int type) { return type == 0 ? "Header" : "Row"; }
    void onBindViewHolder(int pos) { System.out.println("  bind " + attached.get(pos) + " <- '" + data.get(pos) + "'"); }
    void layoutAll() {
        attached.clear();
        for (int i = 0; i < data.size(); i++) {
            attached.add(onCreateViewHolder(getItemViewType(i)));
            onBindViewHolder(i);
        }
    }
    // كل إشعار يحدد نطاق التغيير، فيُعاد ربط ما تأثر فقط
    void notifyItemChanged(int pos) { System.out.println("notifyItemChanged(" + pos + ")"); onBindViewHolder(pos); }
    void notifyItemInserted(int pos) {
        System.out.println("notifyItemInserted(" + pos + ")");
        attached.add(pos, onCreateViewHolder(getItemViewType(pos)));
        onBindViewHolder(pos);
