class Intent {
    String action, target;                       // target != null => explicit
    Map<String, String> extras = new LinkedHashMap<>();
    Intent(String action, String target) { this.action = action; this.target = target; }
    Intent putExtra(String k, String v) { extras.put(k, v); return this; }
}

public class Main {
    static Map<String, List<String>> manifest = new LinkedHashMap<>();   // activity -> intent-filter actions

    static String resolve(Intent i) {
        // الصريحة تسمّي المكوّن مباشرة، والضمنية تبحث في فلاتر الـ manifest
        if (i.target != null) return i.target + " (explicit)";
        List<String> hits = new ArrayList<>();
        for (Map.Entry<String, List<String>> e : manifest.entrySet())
            if (e.getValue().contains(i.action)) hits.add(e.getKey());
        return hits.isEmpty() ? "ActivityNotFoundException" : hits + " (implicit)";
    }

    public static void main(String[] args) {
        manifest.put("DetailActivity", Arrays.asList("app.VIEW_ITEM"));
        manifest.put("ShareActivity", Arrays.asList("android.intent.action.SEND"));
        manifest.put("MailActivity", Arrays.asList("android.intent.action.SEND", "android.intent.action.SENDTO"));
        Intent[] intents = {
            new Intent(null, "DetailActivity").putExtra("id", "42"),
            new Intent("android.intent.action.SEND", null).putExtra("text", "hi"),
            new Intent("android.intent.action.DIAL", null) };
        for (Intent i : intents)
            System.out.println(i.action + " " + i.extras + " -> " + resolve(i));
    }
}

