class Note {
    int id; String title; boolean done;
    Note(int id, String title, boolean done) { this.id = id; this.title = title; this.done = done; }

    String toJson() {
        // نهرّب الشرطة المائلة وعلامة الاقتباس حتى لا يكسر العنوان بنية JSON
        String t = title.replace("\\", "\\\\").replace("\"", "\\\"");
        return "{\"id\":" + id + ",\"title\":\"" + t + "\",\"done\":" + done + "}";
    }

    static String field(String json, String key) {
        int i = json.indexOf("\"" + key + "\":") + key.length() + 3;
        StringBuilder sb = new StringBuilder();
        if (json.charAt(i) == '"') {
            for (i++; json.charAt(i) != '"'; i++) {
                if (json.charAt(i) == '\\') i++;          // خذ الحرف بعد الشرطة المائلة كما هو
                sb.append(json.charAt(i));
            }
        } else {
            for (; json.charAt(i) != ',' && json.charAt(i) != '}'; i++) sb.append(json.charAt(i));
        }
        return sb.toString();
    }

    static Note fromJson(String j) {
        return new Note(Integer.parseInt(field(j, "id")), field(j, "title"), Boolean.parseBoolean(field(j, "done")));
    }
}

public class Main {
    public static void main(String[] args) {
        Note n = new Note(7, "Read \"Android\" chapter", true);
        String json = n.toJson();
        System.out.println(json);
        Note back = Note.fromJson(json);
        System.out.println(back.id + " | " + back.title + " | " + back.done);
        System.out.println("round trip equal: " + back.toJson().equals(json));
    }
}

