abstract class SQLiteOpenHelper {
    int version; SQLiteDatabase db = new SQLiteDatabase();
    SQLiteOpenHelper(int version) { this.version = version; }
    abstract void onCreate(SQLiteDatabase db);
    abstract void onUpgrade(SQLiteDatabase db, int oldV, int newV);
    SQLiteDatabase getWritableDatabase() {
        int old = SQLiteDatabase.diskVersion;
        if (old == 0) { System.out.println("  onCreate"); onCreate(db); }
        else if (old < version) { System.out.println("  onUpgrade " + old + " -> " + version); onUpgrade(db, old, version); }
        else System.out.println("  open as is (v" + old + ")");
        SQLiteDatabase.diskVersion = version;
        return db;
    }
}

public class Main extends SQLiteOpenHelper {
    Main(int v) { super(v); }
    void onCreate(SQLiteDatabase db) { db.execSQL("CREATE TABLE notes(_id INTEGER PRIMARY KEY, title TEXT)"); }
    void onUpgrade(SQLiteDatabase db, int o, int n) { db.execSQL("ALTER TABLE notes ADD COLUMN pinned INTEGER DEFAULT 0"); }
    static void launch(int version, String... titles) {
        System.out.println("launch (version " + version + ")");
        SQLiteDatabase db = new Main(version).getWritableDatabase();
        for (String t : titles) System.out.println("  inserted row " + db.insert(Map.of("title", t)));
    }
    public static void main(String[] args) {
        launch(1, "milk", "exam");
        launch(2, "lab report");      // رفع الإصدار يستدعي onUpgrade ولا يمسح الصفوف
        launch(2);
        System.out.println("rows kept: " + SQLiteDatabase.notes.size());
    }
}

class Cursor {
    String[] cols; Object[][] rows; int pos = -1; boolean closed;
    Cursor(String[] cols, Object[][] rows) { this.cols = cols; this.rows = rows; }
    int getCount() { return rows.length; }
    int getPosition() { return pos; }
    boolean moveToNext() { if (pos < rows.length) pos++; return pos < rows.length; }
    boolean isAfterLast() { return pos >= rows.length; }
    int getColumnIndex(String name) {
        for (int i = 0; i < cols.length; i++) if (cols[i].equals(name)) return i;
        return -1;
    }
    Object get(int col) {
        if (closed) throw new IllegalStateException("cursor closed");
        if (pos < 0 || pos >= rows.length) throw new RuntimeException("CursorIndexOutOfBounds: index " + pos + ", count " + rows.length);
        return rows[pos][col];
    }
    String getString(int c) { return (String) get(c); }
    int getInt(int c) { return (Integer) get(c); }
    void close() { closed = true; }
}

public class Main {
    public static void main(String[] args) {
        Cursor c = new Cursor(new String[]{"_id", "name", "score"},
            new Object[][]{{1, "ana", 90}, {2, "sam", 72}, {3, "lee", 85}});
        System.out.println("count=" + c.getCount() + " position=" + c.getPosition());
        try { c.getString(1); } catch (RuntimeException e) { System.out.println("read before move: " + e.getMessage()); }
        int nameCol = c.getColumnIndex("name"), scoreCol = c.getColumnIndex("score");
        System.out.println("columns: name=" + nameCol + " score=" + scoreCol + " missing=" + c.getColumnIndex("age"));
        while (c.moveToNext())                     // moveToNext يتحرك أولاً ثم يختبر وجود صف
            System.out.println("row " + c.getPosition() + ": " + c.getString(nameCol) + " " + c.getInt(scoreCol));
        System.out.println("after loop: position=" + c.getPosition() + " afterLast=" + c.isAfterLast());
        c.close();
        try { c.getString(nameCol); } catch (RuntimeException e) { System.out.println("read after close: " + e.getMessage()); }
    }
}

