import java.util.*;

public class Main {
    static class State { Object value; State(Object v) { value = v; } }
    static final Object NEVER = new Object();
    static List<Object> slots = new ArrayList<>();           // الـ hooks تُخزَّن بترتيب استدعائها
    static int cursor = 0, renders = 0;

    static State useState(Object init) {
        if (cursor == slots.size()) slots.add(new State(init));      // أول رسم فقط
        return (State) slots.get(cursor++);
    }
    static void useEffect(Runnable effect, Object dep) {
        if (cursor == slots.size()) slots.add(new Object[]{NEVER});
        Object[] last = (Object[]) slots.get(cursor++);
        if (!Objects.equals(last[0], dep)) { last[0] = dep; effect.run(); }
    }
    static void app() {
        cursor = 0; renders++;
        State count = useState(0), name = useState("ana");
        System.out.println("render #" + renders + ": " + name.value + " clicked " + count.value);
        useEffect(() -> System.out.println("  effect: count is " + count.value), count.value);
    }
    static void set(int slot, Object v) {
        State s = (State) slots.get(slot);
        if (Objects.equals(s.value, v)) { System.out.println("set slot " + slot + " = " + v + " -> bail out"); return; }
        s.value = v;
        app();
    }

    public static void main(String[] args) {
        app();
        set(0, 1);
        set(1, "bob");
        set(0, 1);
        set(0, 2);
        System.out.println("renders=" + renders + " slots=" + slots.size());
    }
}

