        createView("Image", "logo.png");
        System.out.println("JS ran 3 createView calls, queued=" + bridge.size());
        flush();
        createView("Text", "Updated");
        flush();
        System.out.println("views created: " + (nextTag - 1) + ", queued=" + bridge.size());
    }
}

