class El {
    String type; Map<String, String> props = new LinkedHashMap<>(); Object[] kids;
    El(String type, String props, Object... kids) {
        this.type = type; this.kids = kids;
        if (props != null) for (String kv : props.split(",")) this.props.put(kv.split("=")[0], kv.split("=")[1]);
    }
}

public class Main {
    // ما نكتبه وسوماً هو في الحقيقة استدعاءات createElement متداخلة
    static String compiled(Object o) {
        if (o instanceof String) return "\"" + o + "\"";
        El e = (El) o;
        List<String> ps = new ArrayList<>();
        for (Map.Entry<String, String> p : e.props.entrySet()) ps.add(p.getKey() + ": \"" + p.getValue() + "\"");
        StringBuilder sb = new StringBuilder("createElement(\"" + e.type + "\", " + (ps.isEmpty() ? "null" : "{" + String.join(", ", ps) + "}"));
        for (Object k : e.kids) sb.append(", ").append(compiled(k));
        return sb.append(")").toString();
    }

    static String html(Object o) {
        if (o instanceof String) return (String) o;
        El e = (El) o;
        StringBuilder sb = new StringBuilder("<" + e.type);
        for (Map.Entry<String, String> p : e.props.entrySet()) sb.append(" " + p.getKey() + "=\"" + p.getValue() + "\"");
        sb.append(">");
        for (Object k : e.kids) sb.append(html(k));
        return sb.append("</" + e.type + ">").toString();
    }

    public static void main(String[] args) {
        El tree = new El("div", "id=app", new El("h1", null, "Hello"),
            new El("ul", null, new El("li", null, "a"), new El("li", "lang=en", "b")));
        System.out.println(compiled(tree));
        System.out.println(html(tree));
    }
}

