public class Main {
    static Map<String, String> RENAME = new HashMap<>();
    static Set<String> VOID = new HashSet<>(Arrays.asList("input", "br", "img", "hr"));

    static String jsxAttr(String a) { return RENAME.getOrDefault(a, a); }      // data-* و aria-* تبقى كما هي

    static String styleObj(String css) {           // style نصٌّ في HTML وكائن camelCase في JSX
        List<String> out = new ArrayList<>();
        for (String decl : css.split(";")) {
            String[] kv = decl.split(":");
            StringBuilder key = new StringBuilder();
            for (String part : kv[0].split("-"))
                key.append(key.length() == 0 ? part : Character.toUpperCase(part.charAt(0)) + part.substring(1));
            out.add(key + ": '" + kv[1] + "'");
        }
        return "style={{" + String.join(", ", out) + "}}";
    }

    public static void main(String[] args) {
        for (String p : "class=className for=htmlFor tabindex=tabIndex onclick=onClick maxlength=maxLength readonly=readOnly".split(" "))
            RENAME.put(p.split("=")[0], p.split("=")[1]);
        for (String a : new String[]{"class", "for", "onclick", "readonly", "data-id", "aria-label"})
            System.out.println(a + " -> " + jsxAttr(a));
        for (String t : new String[]{"input", "div", "br"})
            System.out.println("<" + t + "> -> " + (VOID.contains(t) ? "<" + t + " />" : "<" + t + "></" + t + ">"));
        System.out.println(styleObj("font-size:12px;background-color:red"));
        for (String t : new String[]{"div", "Card"})
            System.out.println(t + " is a " + (Character.isUpperCase(t.charAt(0)) ? "component" : "DOM element"));
    }
}

