public class Main {
    static Map<String, Object> scope = new HashMap<>();

    @SuppressWarnings("unchecked")
    static String render(String tag, String text) {
        Object cur = scope;
        for (String part : tag.split("\\.")) {        // Menu.Item تعني: الخاصية Item داخل Menu
            if (!(cur instanceof Map) || !((Map<String, Object>) cur).containsKey(part))
                return "Error: " + tag + " is undefined (stopped at " + part + ")";
            cur = ((Map<String, Object>) cur).get(part);
        }
        return ((Function<String, String>) cur).apply(text);
    }

    public static void main(String[] args) {
        Map<String, Object> menu = new HashMap<>(), form = new HashMap<>();
        menu.put("Item", (Function<String, String>) t -> "<li class=menu-item>" + t + "</li>");
        menu.put("Divider", (Function<String, String>) t -> "<hr>");
        form.put("Input", (Function<String, String>) t -> "<input placeholder=" + t + ">");
        scope.put("Menu", menu);
        scope.put("Form", form);
        String[][] calls = {{"Menu.Item", "Home"}, {"Menu.Divider", ""}, {"Form.Input", "Email"},
                            {"Menu.Header", "x"}, {"Nav.Item", "x"}};
        for (String[] c : calls) System.out.println(c[0] + " => " + render(c[0], c[1]));
    }
}

import java.util.*;
import java.util.function.*;

public class Main {
    // JSX لا يرسم null ولا true ولا false، لكنه يرسم الرقم 0
    static String child(Object v) { return (v == null || v instanceof Boolean) ? "" : String.valueOf(v); }

    static String jsx(Object... parts) {
        StringBuilder sb = new StringBuilder();
        for (Object p : parts) sb.append(child(p));
        return sb.toString();
    }

    static boolean truthy(Object v) {
        return !(v == null || Boolean.FALSE.equals(v) || Integer.valueOf(0).equals(v) || "".equals(v));
    }
    // && في JavaScript يعيد المعامل الأيسر نفسه إن كان falsy ولا يقيّم الأيمن
    static Object and(Object left, Supplier<Object> right) { return truthy(left) ? right.get() : left; }

    public static void main(String[] args) {
        int count = 3;
        String user = null;
        List<String> items = new ArrayList<>();
        Function<Integer, String> price = n -> "$" + n + ".00";
        System.out.println("{count * 2 + 1} -> " + jsx("<p>", count * 2 + 1, "</p>"));
        System.out.println("{count > 2 ? 'many' : 'few'} -> " + jsx("<p>", count > 2 ? "many" : "few", "</p>"));
        System.out.println("{price(5)} -> " + jsx("<p>", price.apply(5), "</p>"));
        System.out.println("{user && <b>} -> " + jsx("<p>", and(user, () -> "<b>" + user + "</b>"), "</p>"));
        System.out.println("{items.length && <li>} -> " + jsx("<ul>", and(items.size(), () -> "<li>x</li>"), "</ul>"));
        System.out.println("{items.length > 0 && <li>} -> " + jsx("<ul>", and(items.size() > 0, () -> "<li>x</li>"), "</ul>"));
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    static String[] row(String id, String name) { return new String[]{id, name}; }

    // map يحوّل كل عنصر بيانات إلى عنصر واجهة، والـ key يعرّف هويته
    static String html(List<String[]> rows) {
        return rows.stream().map(r -> "<li key=" + r[0] + ">" + r[1] + "</li>").collect(Collectors.joining());
    }
    static Set<String> keys(List<String[]> rows) {
        Set<String> s = new HashSet<>();
        for (String[] r : rows) s.add(r[0]);
        return s;
    }
    static int opsByIndex(List<String[]> a, List<String[]> b) {
        int ops = 0;
        for (int i = 0; i < Math.max(a.size(), b.size()); i++)
            if (i >= a.size() || i >= b.size() || !a.get(i)[1].equals(b.get(i)[1])) ops++;
        return ops;
    }
    static int opsByKey(List<String[]> a, List<String[]> b) {
        Set<String> removed = keys(a), created = keys(b);
        removed.removeAll(keys(b));
        created.removeAll(keys(a));
        return removed.size() + created.size();
    }
    static void report(String label, List<String[]> a, List<String[]> b) {
        System.out.println(label + ": " + html(a) + " -> " + html(b));
        System.out.println("  without keys: " + opsByIndex(a, b) + " ops, with keys: " + opsByKey(a, b) + " ops");
    }

    public static void main(String[] args) {
        List<String[]> abc = Arrays.asList(row("1", "Ana"), row("2", "Bob"), row("3", "Cy"));
        report("remove first", abc, Arrays.asList(row("2", "Bob"), row("3", "Cy")));
        report("insert first", abc, Arrays.asList(row("4", "Dee"), row("1", "Ana"), row("2", "Bob"), row("3", "Cy")));
    }
}

import java.util.*;

public class Main {
    static List<String> fragment(String... kids) { return Arrays.asList(kids); }       // <> ... </> لا يضيف عقدة
    static List<String> div(String... kids) { return List.of("<div>" + String.join("", kids) + "</div>"); }

    // <tr> يقبل <td> مباشرةً فقط، فأي غلاف إضافي يكسر الجدول
    static boolean validInTr(List<String> nodes) {
        for (String n : nodes) if (!n.startsWith("<td>")) return false;
        return true;
    }

    static void show(String label, List<String> nodes) {
        System.out.println(label + ": " + nodes.size() + " root node(s), valid in <tr>: " + validInTr(nodes));
        System.out.println("  <tr>" + String.join("", nodes) + "</tr>");
    }

    public static void main(String[] args) {
        String name = "<td>Name</td>", age = "<td>Age</td>";
        show("div wrapper", div(name, age));
        show("fragment", fragment(name, age));
    }
}
